// Segundo intento (B): mismos importes, pero con número español bien leído y tres comprobaciones.
// Importe español: "1.890,40" → 1890.40 (el punto separa miles; la coma, decimales).
const num = (s) => { if (s == null) return null; const n = Number(s.replace(/\./g, '').replace(',', '.')); return Number.isFinite(n) ? n : null; };
const out = [];
for (const item of $input.all()) {
  const t = item.json.text || '';
  const row = { archivo: item.json.fileName, estado: null, motivo: null, base: null, iva: null, total: null, iva_calculado: null, diferencia: null, numero: null, fecha: null, proveedor: null };
  if (!t.trim()) { row.estado = 'sin_texto'; row.motivo = 'El PDF no tiene capa de texto (imagen escaneada): requiere OCR. No se inventa ningún importe.'; out.push({ json: row }); continue; }
  row.numero = (t.match(/N[ºo°]\s*(\d{4}\/\d{3})/) || [])[1] || null;
  const f = t.match(/Fecha:\s*(\d{2})\/(\d{2})\/(\d{4})/);
  row.fecha = f ? f[3] + '-' + f[2] + '-' + f[1] : null;
  const lines = t.split('\n').map((l) => l.trim()).filter(Boolean);
  const iNif = lines.findIndex((l) => /^NIF\s+[A-Z]\d{8}$/.test(l) && !/B99999999/.test(l));
  row.proveedor = iNif > 0 ? lines[iNif - 1] : null;
  row.base = num((t.match(/(?:Base imponible|Importe neto)\s*([\d.,]+)\s*€/) || [])[1]);
  row.iva = num((t.match(/(?:IVA\s*\(\d+\s*%\)|Cuota IVA\s*\d+%)\s*([\d.,]+)\s*€/) || [])[1]);
  row.total = num((t.match(/(?:TOTAL|Importe total)\s*([\d.,]+)\s*€/) || [])[1]);
  const faltan = ['numero', 'fecha', 'proveedor', 'base', 'iva', 'total'].filter((k) => row[k] == null);
  if (faltan.length) { row.estado = 'revisar'; row.motivo = 'No se encontró: ' + faltan.join(', '); out.push({ json: row }); continue; }
  row.iva_calculado = Math.round((row.base + row.iva) * 100) / 100;
  row.diferencia = Math.round((row.total - row.iva_calculado) * 100) / 100;
  if (Math.abs(row.diferencia) > 0.01) { row.estado = 'revisar'; row.motivo = 'No cuadra: base + IVA = ' + row.iva_calculado.toFixed(2) + ' pero el total impreso es ' + row.total.toFixed(2); }
  else { row.estado = 'ok'; row.motivo = 'Base + IVA = total; los seis campos encontrados'; }
  out.push({ json: row });
}
// Criba: primero lo que hay que mirar (sin_texto, revisar) y después las correctas; dentro de cada grupo, por archivo.
const orden = { sin_texto: 0, revisar: 1, ok: 2 };
out.sort((a, b) => (orden[a.json.estado] - orden[b.json.estado]) || a.json.archivo.localeCompare(b.json.archivo));
return out;
